Topshiriq:

MATLAB da ikki o'lchovli signalni DCT asosida siqishni amalga oshirish:

%% 2D-DCT asosida rasm siqish

clear; clc; close all;

% Rasmni yuklash

img = imread('1.jpg');

img = rgb2gray(img);

img = double(img);

% --- Siqish darajasi ---

Q = 80;   % Q ni o'zgartirib siqish kuchini boshqarasiz (masalan: 20, 40, 80)

[H, W] = size(img);

recon = zeros(H, W);

% 8x8 bloklar bo'yicha DCT asosida siqish

for i = 1:8:H

for j = 1:8:W

block = img(i:i+7, j:j+7);

% DCT

d = dct2(block);

% Kvantlash

d = round(d / Q);

% Tiklash uchun qayta ko'paytirish

d = d * Q;

% IDCT

recon(i:i+7, j:j+7) = idct2(d);

end

end

% Yakuniy rasm

recon = uint8(recon);

% Natijani saqlash

imwrite(recon, ['compressed_Q1' num2str(Q) '.png']);

% Ko'rsatish

figure;

subplot(1,2,1); imshow(uint8(img)); title('Original');

subplot(1,2,2); imshow(recon); title(['DCT siqilgan (Q = ' num2str(Q) ')']);

